static unsigned checks;
#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"%s:%d: %s\n",__FILE__,__LINE__,#x);exit(2);}}while(0)
typedef struct {FILE*file;EVP_MD_CTX*digest;unsigned reads,cancels,fail_at,cancel_at;} Provider;
static CohStatus read_at(void*ctx,uint32_t at,uint8_t*out,size_t n){Provider*p=ctx;p->reads++;if(p->fail_at&&p->reads==p->fail_at)return COH_IO;if(fseek(p->file,(long)at,SEEK_SET)||fread(out,1,n,p->file)!=n)return COH_IO;return COH_OK;}
static CohStatus begin(void*ctx){Provider*p=ctx;return EVP_DigestInit_ex(p->digest,EVP_sha256(),NULL)==1?COH_OK:COH_IO;}
static CohStatus update(void*ctx,CohBytes b){Provider*p=ctx;return EVP_DigestUpdate(p->digest,b.data,b.size)==1?COH_OK:COH_IO;}
static CohStatus finish(void*ctx,uint8_t out[32]){Provider*p=ctx;unsigned n;return EVP_DigestFinal_ex(p->digest,out,&n)==1&&n==32?COH_OK:COH_IO;}
static void abort_digest(void*ctx){(void)ctx;}
static int cancelled(void*ctx){Provider*p=ctx;p->cancels++;return p->cancel_at&&p->cancels==p->cancel_at;}
static CohStatus sha256(void*ctx,CohBytes b,uint8_t out[32]){(void)ctx;unsigned n;return EVP_Digest(b.data,b.size,out,&n,EVP_sha256(),NULL)==1&&n==32?COH_OK:COH_IO;}
static uint32_t word(FILE*f){uint8_t b[4];CHECK(fread(b,1,4,f)==4);return(uint32_t)b[0]|(uint32_t)b[1]<<8|(uint32_t)b[2]<<16|(uint32_t)b[3]<<24;}
static CohBytes load(const char*path){FILE*f=fopen(path,"rb");CHECK(f);CHECK(!fseek(f,0,SEEK_END));long n=ftell(f);CHECK(n>0);CHECK(!fseek(f,0,SEEK_SET));uint8_t*b=malloc((size_t)n);CHECK(b);CHECK(fread(b,1,(size_t)n,f)==(size_t)n);CHECK(!fclose(f));return(CohBytes){b,(size_t)n};}
static CohPowerCategoryDictionary*cats;static CohPowerSetDictionary*sets;static CohPowerStreamDictionary*pows;static CohPowerJoin*out,*saved;static CohPowerJoinWorkspace*workspace;
int main(int argc,char**argv){CHECK(argc==6);CohBytes catbytes=load(argv[1]),setbytes=load(argv[2]);cats=calloc(1,sizeof(*cats));sets=calloc(1,sizeof(*sets));pows=calloc(1,sizeof(*pows));out=malloc(sizeof(*out));saved=malloc(sizeof(*saved));workspace=malloc(sizeof(*workspace));CHECK(cats&&sets&&pows&&out&&saved&&workspace);memset(out,0x5a,sizeof(*out));*saved=*out;CohCostumeImportDigest digest={0};digest.sha256=sha256;uint8_t hash[32];CHECK(sha256(NULL,catbytes,hash)==COH_OK);CohPowerCategoryWorkspace*cw=malloc(sizeof(*cw));CHECK(cw);CHECK(coh_power_categories_read(catbytes,1,hash,&digest,cats,cw,COH_CATEGORY_RAM_MAX,0)==COH_OK);free(cw);free((void*)catbytes.data);
 CHECK(sha256(NULL,setbytes,hash)==COH_OK);CohPowerSetWorkspace*sw=malloc(sizeof(*sw));CHECK(sw);CHECK(coh_power_sets_read(setbytes,2,hash,&digest,sets,sw,COH_POWER_SET_RAM_MAX,0)==COH_OK);free(sw);
 Provider provider={0};provider.file=fopen(argv[3],"rb");provider.digest=EVP_MD_CTX_new();CHECK(provider.file&&provider.digest);CHECK(!fseek(provider.file,0,SEEK_END));long size=ftell(provider.file);CHECK(size>0&&size<=COH_POWER_STREAM_MAX);CHECK(!fseek(provider.file,0,SEEK_SET));CHECK(begin(&provider)==COH_OK);uint8_t buffer[4096];size_t n;while((n=fread(buffer,1,sizeof(buffer),provider.file))!=0)CHECK(update(&provider,(CohBytes){buffer,n})==COH_OK);CHECK(!ferror(provider.file));CHECK(finish(&provider,hash)==COH_OK);CohPowerStreamProvider pp={&provider,sizeof(provider),16384,(uint32_t)size,3,read_at,begin,update,finish,abort_digest,cancelled};CohPowerStreamWorkspace*pw=malloc(sizeof(*pw));CHECK(pw);CHECK(coh_power_stream_read(&pp,hash,pows,pw,COH_POWER_STREAM_RAM_MAX,0)==COH_OK);free(pw);
 provider.reads=provider.cancels=0;CHECK(coh_power_join_prepare(cats,sets,pows,out,workspace,COH_POWER_JOIN_RAM_MAX,0)==COH_OK);
 CohPowerIDs*ids=malloc(sizeof(*ids)),*prior=malloc(sizeof(*prior));CohPowerIDsWorkspace*iw=malloc(sizeof(*iw));CHECK(ids&&prior&&iw);memset(ids,0x5a,sizeof(*ids));*prior=*ids;provider.reads=provider.cancels=0;CHECK(coh_power_ids_prepare(out,ids,iw,COH_POWER_IDS_RAM_MAX,0)==COH_OK);CHECK(!provider.reads&&!provider.cancels);CHECK(ids->source_id_projection&&!ids->complete_finalization&&!ids->runtime_generation&&!ids->actor_authority);FILE*exp=fopen(argv[4],"rb");CHECK(exp);CHECK(ids->category_count==word(exp));CHECK(ids->set_count==word(exp));CHECK(ids->power_count==word(exp));CHECK(ids->assigned_power_count==word(exp));
 for(unsigned i=0;i<ids->category_count;i++)CHECK(ids->sorted_categories[i]==word(exp));
 for(unsigned i=0;i<ids->set_count;i++)CHECK(ids->set_parent_categories[i]==word(exp));
 for(unsigned i=0;i<ids->power_count;i++){CohPowerRuntimeID id=ids->ids[i];CHECK(id.assigned==word(exp));if(id.assigned){CHECK(id.category==word(exp));CHECK(id.set==word(exp));CHECK(id.power==word(exp));}CHECK(ids->power_parent_sets[i]==word(exp));}
 for(unsigned ci=0;ci<ids->category_count;ci++){const CohPowerCategoryEntry*cat=&cats->entries[ids->sorted_categories[ci]];for(unsigned si=0;si<cat->set_count;si++){uint32_t row=out->category_sets[cat->set_first+si];CohPowerJoinSet*set=&out->set_links[row];for(unsigned pi=0;pi<set->count;pi++){uint32_t found=0xabababab;CHECK(coh_power_ids_find(ids,ci,si,pi,&found)==COH_OK);CHECK(found==out->power_links[set->first+pi].resolved_power);}}}
 CHECK(word(exp)==0xabcdef01);CHECK(fgetc(exp)==EOF);CHECK(!fclose(exp));*prior=*ids;
 CHECK(coh_power_ids_prepare(out,ids,iw,1,0)==COH_LIMIT);CHECK(!memcmp(ids,prior,sizeof(*ids)));CHECK(coh_power_ids_prepare(out,ids,iw,COH_POWER_IDS_RAM_MAX,COH_POWER_IDS_RAM_MAX)==COH_LIMIT);CHECK(!memcmp(ids,prior,sizeof(*ids)));CHECK(coh_power_ids_prepare(out,ids,(CohPowerIDsWorkspace*)ids,COH_POWER_IDS_RAM_MAX,0)==COH_INVALID);CHECK(!memcmp(ids,prior,sizeof(*ids)));
 out->complete_forward_join=0;CHECK(coh_power_ids_prepare(out,ids,iw,COH_POWER_IDS_RAM_MAX,0)==COH_STATE);out->complete_forward_join=1;CHECK(!memcmp(ids,prior,sizeof(*ids)));
 if(out->category_reference_count){uint32_t old=out->category_sets[0];out->category_sets[0]=COH_POWER_SET_MAX;CHECK(coh_power_ids_prepare(out,ids,iw,COH_POWER_IDS_RAM_MAX,0)==COH_STATE);out->category_sets[0]=old;CHECK(!memcmp(ids,prior,sizeof(*ids)));}
 if(out->power_reference_count){uint32_t old=out->power_links[0].resolved_power;out->power_links[0].resolved_power=COH_POWER_STREAM_RECORD_MAX;CHECK(coh_power_ids_prepare(out,ids,iw,COH_POWER_IDS_RAM_MAX,0)==COH_STATE);out->power_links[0].resolved_power=old;CHECK(!memcmp(ids,prior,sizeof(*ids)));}
 if(cats->count>1){CohOriginText old=cats->entries[cats->count-1].fields[1];cats->entries[cats->count-1].fields[1]=cats->entries[0].fields[1];CHECK(coh_power_ids_prepare(out,ids,iw,COH_POWER_IDS_RAM_MAX,0)==COH_STATE);cats->entries[cats->count-1].fields[1]=old;CHECK(!memcmp(ids,prior,sizeof(*ids)));}
 CHECK(coh_power_ids_find(ids,0,0,0,(uint32_t*)sets->input.data)==COH_INVALID);CHECK(!memcmp(ids,prior,sizeof(*ids)));
 uint32_t found=0xabababab;CHECK(coh_power_ids_find(ids,COH_CATEGORY_MAX,0,0,&found)==COH_NOT_FOUND);CHECK(found==0xabababab);CHECK(coh_power_ids_find(ids,0,UINT32_MAX,0,&found)==COH_NOT_FOUND);CHECK(found==0xabababab);CHECK(coh_power_ids_find(ids,0,0,UINT32_MAX,&found)==COH_NOT_FOUND);CHECK(found==0xabababab);CHECK(coh_power_ids_find(ids,0,0,0,(uint32_t*)ids)==COH_INVALID);CHECK(!memcmp(ids,prior,sizeof(*ids)));CHECK(!provider.reads&&!provider.cancels);
 printf("{\"checks\":%u,\"assigned_powers\":%u,\"category_rows\":%u,\"owner_bytes\":%zu,\"workspace_bytes\":%zu}\n",checks,ids->assigned_power_count,ids->category_count,sizeof(*ids),sizeof(*iw));free(ids);free(prior);free(iw);CHECK(!fclose(provider.file));EVP_MD_CTX_free(provider.digest);free((void*)setbytes.data);free(cats);free(sets);free(pows);free(out);free(saved);free(workspace);return 0;}
